import{_ as u,a0 as p,w as s,s as n,ao as a,I as r,x as t,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何為開源軟件寫作文章 | LCTT x X-CMD","titleTemplate":false,"description":"如何為開源軟件寫作文章 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何為開源軟件寫作文章 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何為開源軟件寫作文章 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200526 How to write about open source software","title":"如何為開源軟件寫作文章","tag":"202005","desc":""},"relativePath":"202005/20200526 How to write about open source software.md","filePath":"[post].md"}'),m={name:"202005/20200526 How to write about open source software.md"};function d(f,l,b,w,y,g){const e=p("Link");return s(),n("div",null,[l[35]||(l[35]=a('<h1 id="如何為開源軟件寫作文章" tabindex="-1">如何為開源軟件寫作文章 <a class="header-anchor" href="#如何為開源軟件寫作文章" aria-label="Permalink to “如何為開源軟件寫作文章”">​</a></h1><blockquote><p>通過以下提示，成為一個更好的作者。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/31/115044ecfpxc2q9z0ca8wq.jpg" alt=""></p><p>開始接觸開源社區的一個方法就是寫關於它的文章。你可以貢獻技術文檔，分享你如何使用軟件，或者為我們社區寫一篇文章。但是開始寫作説起來容易做起來難。我聽到的最常見的兩個不寫文章的藉口是：“我沒有什麼新東西可寫”和“我不是一個好的作者”。我在這裏是為了打破這兩個誤區。</p><h3 id="你應該寫什麼" tabindex="-1">你應該寫什麼？ <a class="header-anchor" href="#你應該寫什麼" aria-label="Permalink to “你應該寫什麼？”">​</a></h3><blockquote><p>“尋找那些經常被遺漏的故事。” 埃裏克·拉爾森</p></blockquote><p>對於某些人來説，寫作的最大障礙是找到要寫的想法或話題。很容易就落入了這樣的思維陷阱：“這個話題已經寫過了，何必再麻煩。”</p><p>我不是第一個寫文章的人，也不會是最後一個。我帶來的是我獨特的視角和這些年來所學到的東西。曾經有人向我請教過一些關於寫作入門的建議，或者是如何讓自己的寫作更上一層樓。我決定把這些建議變成一篇文章。</p><p>文如其人，沒有人會以你的方式來述事，你的經驗和觀點可能正是別人所需要的。</p><p>這裏有一些提示，可以幫助你想出一個主題：</p><ul><li>你最近學到了什麼東西？寫出你是如何學習的，你學到了什麼，或使你感到驚訝的事情。</li><li>你經常被問到的問題是什麼？把答案寫出來。</li><li>你最近是否在搜索一篇怎麼做的文章，但在搜索結果中，你對排名靠前的文章不滿意？請寫出你要找的文章。</li><li>你是否參加過會議或研討會？寫一篇會後總結來説明你所學到的東西。</li><li>你開始使用新工具了嗎？寫一份操作指南或入門指南。</li></ul><h3 id="你寫的是什麼類型的文章" tabindex="-1">你寫的是什麼類型的文章？ <a class="header-anchor" href="#你寫的是什麼類型的文章" aria-label="Permalink to “你寫的是什麼類型的文章？”">​</a></h3><p>有不同類型的文章，包括:</p><ul><li>技術文檔</li><li>操作指南</li><li>Blog</li><li>白皮書或電子書</li><li>回顧性的文章</li></ul><p>內容的類型會影響你的寫作風格和語氣。Blog更加非正式和是對話式的。而技術文檔更正式，更具有指導性。</p><h3 id="你是為誰而寫的" tabindex="-1">你是為誰而寫的？ <a class="header-anchor" href="#你是為誰而寫的" aria-label="Permalink to “你是為誰而寫的？”">​</a></h3><p>每一篇文章都應該有一個單一的受眾。受眾是指你為之寫作的對象是什麼類型的人。在你開始寫作之前，寫下你的讀者的一些特徵是有助於寫作的。重要的是要考慮到你要為誰寫，以及你<strong>不是為</strong>誰寫的 —— 確定你的目標受眾將決定要包括哪些內容和不包括哪些內容。</p><p>例如，我在寫這篇文章的時候，我設想的目標受眾是這樣的：</p><ul><li>有基本的寫作和語法知識</li><li>有興趣提高寫作能力</li><li>在技術領域擔任開發人員、銷售工程師、客户經理或類似職位的工作</li><li>不是經驗豐富或資深的作者，可能在個人或工作Blog上發表過幾篇文章，想寫更多的文章。</li><li>非虛構寫作</li></ul><p>如果你有針對多個受眾的內容，可以考慮針對不同的受眾將其分解成不同的內容。對你的受眾要考慮的一些方面：</p><ul><li>專業水平：新手、中級、高級</li><li>作用：管理人員、個人貢獻者</li><li>目標：他們為什麼要閲讀這些？</li></ul><h3 id="言語很重要" tabindex="-1">言語很重要 <a class="header-anchor" href="#言語很重要" aria-label="Permalink to “言語很重要”">​</a></h3><p>你選擇的言語會對讀者產生影響。晦澀難懂的詞彙會使文章更難理解，不常見的詞彙會讓讀者覺得自己很笨，某些詞彙可能會不小心冒犯讀者。作為一個作者，你的目標是避免所有這些。下面是怎麼做的：</p><h4 id="使用日常用語" tabindex="-1">使用日常用語 <a class="header-anchor" href="#使用日常用語" aria-label="Permalink to “使用日常用語”">​</a></h4><p>不要把寫作作為炫耀你的詞彙量或你從“每日一字”枱曆上學到的單詞的方式。寫作是為了讓讀者能夠理解。每一篇文章都有相關的閲讀水平。如果你寫的是技術文檔，那麼你的目標大約是初中的閲讀水平。這並不意味着你的受眾只有初中的教育水平。它意味着你的寫作會更容易被人理解。你想讓人們對這些言語過目不忘，還是想讓他們覺得自己學到了什麼？雖然你可以使用長而複雜的詞彙，但並不意味着你應該這樣做。使用簡單的語言不一定意味着你的文章會很無聊。</p>',25)),r("p",null,[l[1]||(l[1]=t("使用 ",-1)),o(e,{href:"http://www.hemingwayapp.com/"},{default:i(()=>[...l[0]||(l[0]=[t("Hemingway 應用",-1)])]),_:1}),l[2]||(l[2]=t("等工具來檢查你的作品的可讀性（它不是開源的，但很優秀）。比如説，在初稿之後，這篇文章被評定為五年級的閲讀水平。Hemingway 還提供瞭如何改進寫作的建議 —— 找出難以理解的句子或需要改變選詞的地方。",-1))]),r("p",null,[l[5]||(l[5]=t("如果你想要找出替代的詞彙，可以查看 ",-1)),o(e,{href:"http://www.plainenglish.co.uk/the-a-z-of-alternative-words.html"},{default:i(()=>[...l[3]||(l[3]=[t("Plain English Campaign",-1)])]),_:1}),l[6]||(l[6]=t(" 的建議或 ",-1)),o(e,{href:"https://www.powerthesaurus.org/"},{default:i(()=>[...l[4]||(l[4]=[t("Power Thesaurus",-1)])]),_:1}),l[7]||(l[7]=t(" 的眾包建議。",-1))]),l[36]||(l[36]=a('<h4 id="知道應該規避哪些詞" tabindex="-1">知道應該規避哪些詞 <a class="header-anchor" href="#知道應該規避哪些詞" aria-label="Permalink to “知道應該規避哪些詞”">​</a></h4><blockquote><p>“每次你想寫‘非常’的時候，就用‘該死的’代替；你的編輯會把它刪掉，而作品就會如它應有的那樣。” 馬克·吐温</p></blockquote><p>在寫教程或指南的時候，這裏有一些要避免的詞，包括“<ruby>簡單<rt>simple</rt></ruby>”、“<ruby>容易<rt>easy</rt></ruby>”和“<ruby>就這樣<rt>just</rt></ruby>”。你是你所寫的主題的專家，經過多年的實踐，可能會覺得事情很簡單。而初學者可能會覺得事情不“簡單”，也不“容易”。你的讀者可能會感到沮喪，因為他們覺得過程或解釋並不簡單。</p><p>你是否曾經因為無法理解作者的意思而不得不反覆重讀一個句子或段落？你有沒有因為一篇文章對你來説沒有意義而放棄過？我有過。</p><p>作為一個作者，你希望你的讀者感到困惑或不理解嗎？我希望不會。</p><p>在你的寫作中要避免的其它詞語：</p><ul><li><ruby>這件事<rt>That</rt></ruby></li><li><ruby>真的<rt>Really</rt></ruby></li><li><ruby>非常<rt>Very</rt></ruby></li><li><ruby>所以<rt>So</rt></ruby></li><li><ruby>為了<rt>In order to</rt></ruby></li></ul><p>一般來説，這些詞可以在不改變句子意思的情況下刪除。</p><p>在我寫完之後，我會在文檔中搜索這些詞。當我在這篇文章中搜索時，我發現了以下這句話：</p><blockquote><p>“這並不意味着你的受眾只有初中的教育水平<em>這件事</em>，而意味着你的寫作會更容易被理解<em>這件事</em>。”</p></blockquote><p>這句話中出現了兩個“<ruby>這件事<rt>That</rt></ruby>”的例子。它們並沒有給句子增加價值。它們可以被刪除而不改變其含義。刪除這些詞彙可以縮短句子，並且更短的句子更容易理解。而説到短句，我還把它改寫成了兩句話。</p><blockquote><p>“這並不意味着你的受眾只有初中的教育水平。它意味着你的寫作會更容易被人理解。”</p></blockquote><h4 id="使用包容性語言" tabindex="-1">使用包容性語言 <a class="header-anchor" href="#使用包容性語言" aria-label="Permalink to “使用包容性語言”">​</a></h4>',13)),r("p",null,[l[9]||(l[9]=t("詞語和短語的歷史背景可能會導致人們感到被排斥或冒犯。在寫作時，你要讓讀者感到被包容。當你使用包容性的語言時，會讓讀者感到被理解、被尊重，感覺被包容。我參考了 Buffer 中的這篇",-1)),o(e,{href:"https://open.buffer.com/inclusive-language-tech/"},{default:i(()=>[...l[8]||(l[8]=[t("關於使用包容性語言的指南",-1)])]),_:1}),l[10]||(l[10]=t("。",-1))]),l[37]||(l[37]=a('<h3 id="修訂和編輯" tabindex="-1">修訂和編輯 <a class="header-anchor" href="#修訂和編輯" aria-label="Permalink to “修訂和編輯”">​</a></h3><blockquote><p>“幾乎所有好的寫作都是從糟糕的第一次努力開始的。你需要從某個地方開始。” 安妮·拉莫特</p></blockquote><p>寫作是一個迭代的過程。如果你認為作者們坐在辦公桌前，在一個小時內就能完成一篇文章準備發表，那麼請你再想一想。有些文章需要我花幾個星期的時間來完成。以下是我的標準流程：</p><ul><li>寫一個粗略的初稿。我説的粗略，我的意思是<em>粗陋</em>。寫的時候不用擔心語法問題。目的是讓文字從我的腦海中浮現出來，寫在紙上。這一步可能需要一個小時到幾周的時間。</li><li>將草稿放一段時間。這可能需要幾個小時到幾天的時間，這取決於出版時間線。</li><li>審閲草稿。進行調整和編輯。</li><li>徵求反饋意見，可以是同事或朋友的反饋意見。在這個階段的反饋中，我的重點是明確性。是否有意義？是否有什麼令人困惑的地方？有什麼缺失的部分？</li><li>納入反饋意見。無論你的寫作經驗有多豐富，讓其他作者審閲你的作品，都會讓你的作品變得更好。</li></ul>',4)),r("p",null,[l[13]||(l[13]=t("在這個階段，我有了一個相當紮實的草稿。現在到了我最不喜歡的寫作部分 —— 編輯。我之前提到的 Hemingway 應用不僅能告訴你閲讀水平，還能提供改進寫作的建議。我還使用 Grammarly 來幫助編輯語法。關於 Grammarly 的開源替代工具，請查看",-1)),o(e,{href:"https://languagetool.org/"},{default:i(()=>[...l[11]||(l[11]=[t("語言工具網站",-1)])]),_:1}),l[14]||(l[14]=t("或這篇文章中的",-1)),o(e,{href:"https://opensource.com/article/20/3/open-source-writing-tools"},{default:i(()=>[...l[12]||(l[12]=[t("開源寫作工具",-1)])]),_:1}),l[15]||(l[15]=t("。",-1))]),l[38]||(l[38]=r("p",null,"我的寫作挑戰之一就是適當地使用逗號。Grammarly 可以幫助我找出我缺失或濫用逗號的地方。Grammarly 發現了 43 個這篇文章的最終草稿的正確性問題。其中大部分是逗號錯誤。",-1)),l[39]||(l[39]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/uploads/grammarlyerrors.png",alt:"Errors identified by Grammarly",title:"Errors identified by Grammarly"})],-1)),l[40]||(l[40]=r("p",null,"除了語法錯誤之外，該應用程序還提供了一些建議，以幫助提高清晰度、參與度和表達能力（其中一些功能可能在免費版中沒有）。這包括單詞選擇和使用主動語氣與被動語氣等。有些建議我接受，有些則拒絕。在審查了所有的警報和建議後，Grammarly 會在各個方面進行反饋。",-1)),l[41]||(l[41]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/uploads/grammarlyresults.png",alt:"Grammarly results",title:"Grammarly results"})],-1)),l[42]||(l[42]=r("p",null,"不要害怕尋求寫作上的幫助。每一個好的作者背後都有一個好的編輯或好的編輯應用。",-1)),l[43]||(l[43]=r("h3",{id:"文體指南",tabindex:"-1"},[t("文體指南 "),r("a",{class:"header-anchor",href:"#文體指南","aria-label":"Permalink to “文體指南”"},"​")],-1)),l[44]||(l[44]=r("p",null,"文體指南為改善書面交流提供了標準。它們包括標點符號、語法和用詞等方面。如果是為你的公司撰寫文檔，請檢查一下公司是否有文體指南。如果沒有文體指南，或者你是為自己寫的，下面是一些常用的文體指南：",-1)),r("ul",null,[r("li",null,[o(e,{href:"https://www.chicagomanualofstyle.org/home.html"},{default:i(()=>[...l[16]||(l[16]=[t("芝加哥文體手冊",-1)])]),_:1})]),r("li",null,[o(e,{href:"https://developers.google.com/style"},{default:i(()=>[...l[17]||(l[17]=[t("谷歌開發者文檔指南",-1)])]),_:1})]),r("li",null,[o(e,{href:"https://docs.microsoft.com/en-us/style-guide/welcome/"},{default:i(()=>[...l[18]||(l[18]=[t("微軟寫作文體指南",-1)])]),_:1})]),r("li",null,[o(e,{href:"https://www.apstylebook.com/"},{default:i(()=>[...l[19]||(l[19]=[t("美聯社文體手冊",-1)])]),_:1})])]),l[45]||(l[45]=r("p",null,"寫作是一種與社區分享自己的思想和知識的方式。開始寫作的唯一方法就是開始打字。用這些建議來微調你的寫作。",-1)),l[46]||(l[46]=r("hr",null,null,-1)),r("p",null,[l[21]||(l[21]=t("via: ",-1)),o(e,{href:"https://opensource.com/article/20/5/write-about-open-source-software"},{default:i(()=>[...l[20]||(l[20]=[t("https://opensource.com/article/20/5/write-about-open-source-software",-1)])]),_:1})]),r("p",null,[l[26]||(l[26]=t("作者：",-1)),o(e,{href:"https://opensource.com/users/dawnparzych"},{default:i(()=>[...l[22]||(l[22]=[t("Dawn Parzych",-1)])]),_:1}),l[27]||(l[27]=t(" 選題：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...l[23]||(l[23]=[t("lujun9972",-1)])]),_:1}),l[28]||(l[28]=t(" 譯者：",-1)),o(e,{href:"https://github.com/wxy"},{default:i(()=>[...l[24]||(l[24]=[t("wxy",-1)])]),_:1}),l[29]||(l[29]=t(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:i(()=>[...l[25]||(l[25]=[t("wxy",-1)])]),_:1})]),r("p",null,[l[32]||(l[32]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...l[30]||(l[30]=[t("LCTT",-1)])]),_:1}),l[33]||(l[33]=t(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:i(()=>[...l[31]||(l[31]=[t("Linux中國",-1)])]),_:1}),l[34]||(l[34]=t(" 榮譽推出",-1))])])}const P=u(m,[["render",d]]);export{x as __pageData,P as default};
